/bin/bash -lc "python3 - <<'PY'
import os,json,urllib.request
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
url='https://usegalaxy.org/api/tools/toolshed.g2.bx.psu.edu/repos/iuc/minimap2/minimap2/2.31+galaxy1?io_details=true'
req=urllib.request.Request(url,headers={'x-api-key':key})
with urllib.request.urlopen(req) as r: data=json.load(r)
# find ref_file select parameter options
for inp in data['inputs']:
    if inp.get('name')=='reference_source':
        for case in inp['cases']:
            if case['value']=='cached':
                for p in case['inputs']:
                    if p.get('name')=='ref_file':
                        opts=p['options']
                        print('num options',len(opts))
                        for label,val,sel in opts:
                            low=(label+' '+val).lower()
                            if any(s in low for s in ['rattus','mus musculus','homo sapiens','rn7','grch38','grcm','mm10','mm39']):
                                print(label,'=>',val)
                        break
PY"

